			break
		}
	}
	for i := range out {
		switch s := &out[i]; s.Kind {
		case stepSource:
			s.WSL = info
		case stepGateway:
			s.WindowsHost = labelled
		case stepHop:
			s.WindowsHost = labelled && s.Hop.TTL == 1 && s.Hop.Addr == host
		}
	}
	return out
}

