1	package wslenv
2	
3	import (
4		"context"
5		"errors"
6		"os"
7		"os/exec"
8		"strings"
9		"time"
10	)
11	
12	const (
13		// wslinfoTimeout bounds the child process.
14		wslinfoTimeout = 2 * time.Second
15		// wslinfoMaxOutput bounds what is read from the child and returned.
16		wslinfoMaxOutput = 64
17		// wslinfoWaitDelay is how long Run waits for I/O after the process is killed.
18		wslinfoWaitDelay = 500 * time.Millisecond
19	)
20	
21	// wslinfoNetworkingMode runs `wslinfo --networking-mode` and returns its
22	// cleaned output. The binary is looked up at two fixed absolute paths, never
23	// through the search path.
24	func wslinfoNetworkingMode(ctx context.Context) (string, error) {
25		path, err := findWslinfo()
26		if err != nil {
27			return "", err
28		}
29		return runWslinfo(ctx, path)
30	}
31	
32	// boundedBuffer keeps the first wslinfoMaxOutput bytes written and drops the
33	// rest, so a chatty child can neither grow memory nor block on a full pipe.
34	type boundedBuffer struct{ buf []byte }
35	
36	func (b *boundedBuffer) Write(p []byte) (int, error) {
37		if room := wslinfoMaxOutput - len(b.buf); room > 0 {
38			b.buf = append(b.buf, p[:min(room, len(p))]...)
39		}
40		return len(p), nil
41	}
42	
43	// runWslinfo runs the binary at path with an empty environment, a 2 s deadline
44	// and bounded output. A done context takes precedence over the process error.
45	func runWslinfo(ctx context.Context, path string) (string, error) {
46		ctx, cancel := context.WithTimeout(ctx, wslinfoTimeout)
47		defer cancel()
48		out := &boundedBuffer{}
49		cmd := exec.CommandContext(ctx, path, "--networking-mode")
50		cmd.Env = []string{}
51		cmd.Stdout = out
52		cmd.WaitDelay = wslinfoWaitDelay
53		if err := cmd.Run(); err != nil {
54			if ctxErr := ctx.Err(); ctxErr != nil {
55				return "", ctxErr
56			}
57			return "", err
58		}
59		return parseWslinfoOutput(out.buf), nil
60	}
61	
62	// findWslinfo returns the first wslinfo binary that exists.
63	func findWslinfo() (string, error) {
64		for _, p := range []string{"/usr/bin/wslinfo", "/usr/sbin/wslinfo"} {
65			if _, err := os.Stat(p); err == nil {
66				return p, nil
67			}
68		}
69		return "", errors.New("wslinfo not found")
70	}
71	
72	// parseWslinfoOutput bounds and cleans the output of `wslinfo --networking-mode`.
73	func parseWslinfoOutput(out []byte) string {
74		s := strings.TrimSpace(string(out))
75		if len(s) > wslinfoMaxOutput {
76			s = s[:wslinfoMaxOutput]
77		}
78		return s
79	}
